import 'dart:convert'; import 'package:http/http.dart' as http; import 'package:supabase_flutter/supabase_flutter.dart';
class Invoice { Invoice.fromJson(Map<String,dynamic> j):id='${j['id']}',number='${j['invoice_number']}',contactId='${j['contact_id']}',currency='${j['currency']??'ZAR'}',total=double.tryParse('${j['total_amount']}')??0,paid=double.tryParse('${j['amount_paid']??0}')??0,outstanding=double.tryParse('${j['outstanding_balance']??j['total_amount']}')??0,status='${j['computed_status']??j['status']}',dueDate='${j['due_date']}',disputed=j['disputed']==true; final String id,number,contactId,currency,dueDate,status; final double total,paid,outstanding; final bool disputed; }
class Payment { Payment.fromJson(Map<String,dynamic> j):amount=double.tryParse('${j['amount']}')??0,date='${j['payment_date']??''}',reference='${j['payment_reference']??''}',status='${j['status']??''}'; final double amount; final String date,reference,status; }
class CollectionPolicy { CollectionPolicy.fromJson(Map<String,dynamic> j):before=j['reminder_before_due_days']??3,after=j['reminder_after_due_days']??1,max=j['maximum_automatic_reminders']??2,automatic=j['automatic_sending_enabled']==true,approval=j['final_demand_requires_approval']!=false,tone='${j['tone']??'professional'}'; final int before,after,max; final bool automatic,approval; final String tone; }
class AccountsRepository { AccountsRepository(this.baseUrl,this.client); final String baseUrl; final SupabaseClient client; Future<Map<String,String>> _h()async{final t=client.auth.currentSession?.accessToken;if(t==null)throw Exception('Sign in required.');return {'Authorization':'Bearer $t','Content-Type':'application/json'};}Future<dynamic> _req(String path,{String method='GET',Map<String,dynamic>? body})async{final h=await _h();final u=Uri.parse('$baseUrl$path');final r=method=='POST'?await http.post(u,headers:h,body:jsonEncode(body??{})):method=='PATCH'?await http.patch(u,headers:h,body:jsonEncode(body??{})):await http.get(u,headers:h);if(r.statusCode>=400)throw Exception('Accounts request failed.');return jsonDecode(r.body);}Future<List<Invoice>> invoices({String? status,String? q,String? contactId})async=>(await _req('/api/v1/accounts/invoices?status=&q=&contact_id='))['invoices'].map<Invoice>((x)=>Invoice.fromJson(Map<String,dynamic>.from(x))).toList();Future<Map<String,dynamic>> accountSummary(String contactId)async=>Map<String,dynamic>.from((await _req('/api/v1/crm/contacts/'+contactId+'/accounts-summary'))['summary']);Future<Map<String,dynamic>> invoice(String id)async=>Map<String,dynamic>.from(await _req('/api/v1/accounts/invoices/$id'));Future<void> updateInvoice(String id,Map<String,dynamic> v)async{await _req('/api/v1/accounts/invoices/' + id,method:'PATCH',body:v);}Future<void> createInvoice(Map<String,dynamic> v)async{await _req('/api/v1/accounts/invoices',method:'POST',body:v);}Future<void> payment(String id,Map<String,dynamic> v)async{await _req('/api/v1/accounts/invoices/$id/payments',method:'POST',body:v);}Future<CollectionPolicy> policy()async=>CollectionPolicy.fromJson(Map<String,dynamic>.from((await _req('/api/v1/accounts/policy'))['policy']??{}));Future<void> savePolicy(Map<String,dynamic> v)async{await _req('/api/v1/accounts/policy',method:'PATCH',body:v);}Future<List<Map<String,dynamic>>> approvals()async=>(await _req('/api/v1/approvals'))['approvals'].map<Map<String,dynamic>>((x)=>Map<String,dynamic>.from(x)).toList();Future<void> resolveApproval(String id,String decision)async{await _req('/api/v1/approvals/$id/resolve',method:'POST',body:{'decision':decision});}Future<Map<String,dynamic>> run()async=>Map<String,dynamic>.from(await _req('/api/v1/agents/accounts/run',method:'POST',body:{}));Future<Map<String,dynamic>> agent()async=>Map<String,dynamic>.from((await _req('/api/v1/agents/accounts'))['agent']??{});Future<void> setAgent(String status)async{await _req('/api/v1/agents/accounts/status',method:'POST',body:{'status':status});}Future<void> dispute(String id,String reason)async{await _req('/api/v1/accounts/invoices/$id/dispute',method:'POST',body:{'reason':reason});}}



